{"command":"cd /tmp/probe && cat > src/main.rs <<'EOF'
use git2::{Repository, Sort, BranchType};
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let repo = Repository::discover(&args[1]).unwrap();
    let modes: Vec<(&str, Sort)> = vec![
        ("topo|time", Sort::TOPOLOGICAL | Sort::TIME),
        ("time", Sort::TIME),
        ("topo", Sort::TOPOLOGICAL),
        ("none", Sort::NONE),
    ];
    let push_modes = ["branches_none", "branches_local_remote", "glob_heads_remotes", "head_then_branches", "glob_all_heads"];
    for (mname, m) in &modes {
        for pm in push_modes.iter() {
            let mut walk = repo.revwalk().unwrap();
            walk.set_sorting(*m).unwrap();
            match *pm {
                "branches_none" => { for b in repo.branches(None).unwrap() { let (b,_) = b.unwrap(); if let Some(t) = b.get().target() { walk.push(t).unwrap(); } } }
                "branches_local_remote" => { for bt in [BranchType::Local, BranchType::Remote] { for b in repo.branches(Some(bt)).unwrap() { let (b,_) = b.unwrap(); if let Some(t) = b.get().target() { walk.push(t).unwrap(); } } } }
                "glob_heads_remotes" => { walk.push_glob("refs/heads/*").unwrap(); walk.push_glob("refs/remotes/*").unwrap(); }
                "head_then_branches" => { let _ = walk.push_head(); for b in repo.branches(None).unwrap() { let (b,_) = b.unwrap(); if let Some(t) = b.get().target() { walk.push(t).unwrap(); } } }
                "glob_all_heads" => { walk.push_glob("heads").unwrap(); walk.push_glob("remotes").unwrap(); }
                _ => {}
            }
            let mut out = vec![];
            for (i, oid) in walk.enumerate() { if i >= 30 { break; } let c = repo.find_commit(oid.unwrap()).unwrap(); out.push(c.summary().unwrap_or("").to_string()); }
            println!("{:10} {:22} {}", mname, pm, out.join(" | "));
        }
    }
}
EOF
