use serde::Deserialize;
use std::time::Duration;

#[derive(Debug, Clone)]
pub struct RefreshConfig {
    pub auto_refresh: bool,
    pub refresh_interval: u64,
    pub auto_fetch: bool,
    pub fetch_interval: u64,
}

impl Default for RefreshConfig {
    fn default() -> Self {
        RefreshConfig {
            auto_refresh: true,
            refresh_interval: 10,
            auto_fetch: true,
            fetch_interval: 60,
        }
    }
}

impl RefreshConfig {
    pub fn refresh_duration(&self) -> Duration {
        Duration::from_secs(self.refresh_interval.max(1))
    }
    pub fn fetch_duration(&self) -> Duration {
        Duration::from_secs(self.fetch_interval.max(10))
    }
}

#[derive(Debug, Default, Deserialize)]
struct RawRefresh {
    auto_refresh: Option<bool>,
    refresh_interval: Option<u64>,
    auto_fetch: Option<bool>,
    fetch_interval: Option<u64>,
}

#[derive(Debug, Default, Deserialize)]
struct RawConfig {
    refresh: Option<RawRefresh>,
}

#[derive(Debug, Clone, Default)]
pub struct Config {
    pub refresh: RefreshConfig,
}

impl Config {
    pub fn load() -> Config {
        let mut cfg = Config::default();
        let path = match dirs::home_dir() {
            Some(h) => h.join(".config").join("keifu").join("config.toml"),
            None => return cfg,
        };
        let content = match std::fs::read_to_string(&path) {
            Ok(c) => c,
            Err(_) => return cfg,
        };
        let raw: RawConfig = match toml::from_str(&content) {
            Ok(r) => r,
            Err(_) => return cfg,
        };
        if let Some(r) = raw.refresh {
            if let Some(v) = r.auto_refresh {
                cfg.refresh.auto_refresh = v;
            }
            if let Some(v) = r.refresh_interval {
                cfg.refresh.refresh_interval = v.max(1);
            }
            if let Some(v) = r.auto_fetch {
                cfg.refresh.auto_fetch = v;
            }
            if let Some(v) = r.fetch_interval {
                cfg.refresh.fetch_interval = v.max(10);
            }
        }
        cfg
    }
}
