                    let ch = if i > target && i < far { '┼' } else { '│' };
                    set_cell(&mut cells, li, Cell::new(ch, l.color));
                } else if i > target && i < far {
                    set_cell(&mut cells, li, Cell::new('─', far_color));
                }
