        let mut cells: Vec<Cell> = Vec::new();
        for (i, l) in before.iter().enumerate() {
            if i == lane {
                continue;
            }
            if let Some(l) = l {
                set_cell(&mut cells, i * 2, Cell::new('│', l.color));
            }
        }
        set_cell(&mut cells, lane * 2, Cell::new('●', color));
        // track which cells were drawn by merge lines
        let mut drawn: Vec<bool> = Vec::new();
        let mark = |drawn: &mut Vec<bool>, idx: usize| {
            if drawn.len() <= idx {
                drawn.resize(idx + 1, false);
            }
            drawn[idx] = true;
        };
        let is_drawn = |drawn: &Vec<bool>, idx: usize| drawn.get(idx).copied().unwrap_or(false);
        for &(t, tc, existing) in &merge_targets {
            let (lo, hi) = if t > lane { (lane * 2, t * 2) } else { (t * 2, lane * 2) };
            for c in (lo + 1)..hi {
                if is_drawn(&drawn, c) {
                    continue;
                }
                let cur = get_cell(&cells, c);
                if c % 2 == 0 {
                    // lane position
                    if cur.ch == '│' {
                        set_cell(&mut cells, c, Cell { ch: '┼', color: cur.color });
                    } else if cur.is_empty() {
                        set_cell(&mut cells, c, Cell::new('─', tc));
                    }
                } else if cur.is_empty() {
                    set_cell(&mut cells, c, Cell::new('─', tc));
                }
                mark(&mut drawn, c);
            }
            let tpos = t * 2;
            if !is_drawn(&drawn, tpos) {
                let ch = match (t > lane, existing) {
                    (true, true) => '┤',
                    (true, false) => '╮',
                    (false, true) => '├',
                    (false, false) => '╭',
                };
                set_cell(&mut cells, tpos, Cell::new(ch, tc));
                mark(&mut drawn, tpos);
            }
        }
        max_lanes = max_lanes.max(lanes.len());
        rows.push(GraphRow {
            kind: RowKind::Commit { index, lane, color },
            cells,
        });
    }

    Graph { rows, width_lanes: max_lanes }
