        Some(r) => match graph.rows[r].kind {
            RowKind::Commit { lane, .. } => (Some(r), lane),
            _ => (None, 0),
        },
        None => (None, 0),
    };
    let lane = match head_row {
        Some(hr) => {
            let mut u = 0usize;
            loop {
                let pos = u * 2;
                let free_above = graph.rows[..hr].iter().all(|r| get_cell(&r.cells, pos).is_empty());
                let ok = free_above
                    && (u == head_lane || get_cell(&graph.rows[hr].cells, pos).is_empty());
                if ok {
                    break u;
                }
                u += 1;
            }
        }
        None => head_lane,
    };
    if let Some(hr) = head_row {
        for r in graph.rows[..hr].iter_mut() {
            set_cell(&mut r.cells, lane * 2, Cell::new('│', UNCOMMITTED_COLOR));
        }
        if lane != head_lane {
            let row = &mut graph.rows[hr];
            let (lo, hi) = if lane > head_lane { (head_lane * 2, lane * 2) } else { (lane * 2, head_lane * 2) };
            for c in (lo + 1)..hi {
                let cur = get_cell(&row.cells, c);
                if c % 2 == 0 && cur.ch == '│' {
                    set_cell(&mut row.cells, c, Cell { ch: '┼', color: cur.color });
                } else if cur.is_empty() {
                    set_cell(&mut row.cells, c, Cell::new('─', UNCOMMITTED_COLOR));
                }
            }
            let ch = if lane > head_lane { '╯' } else { '╰' };
            set_cell(&mut row.cells, lane * 2, Cell::new(ch, UNCOMMITTED_COLOR));
        }
    }
    let mut cells = Vec::new();
    set_cell(&mut cells, lane * 2, Cell::new('●', UNCOMMITTED_COLOR));
    graph.rows.insert(0, GraphRow { kind: RowKind::Uncommitted, cells });
    graph.width_lanes = graph.width_lanes.max(lane + 1);
}

#[allow(dead_code)]
pub fn index_map(rows: &[GraphRow]) -> HashMap<usize, usize> {
    let mut m = HashMap::new();
    for (ri, r) in rows.iter().enumerate() {
        if let RowKind::Commit { index, .. } = r.kind {
            m.insert(index, ri);
        }
    }
    m
}
