//! Git repository access.

use anyhow::{anyhow, Context, Result};
use git2::{BranchType, Delta, DiffOptions, Oid, Repository, Sort, StatusOptions};
use std::collections::HashMap;

pub const MAX_COMMITS: usize = 500;
pub const MAX_FILES: usize = 50;

#[derive(Clone, Debug)]
pub struct CommitInfo {
    pub oid: Oid,
    pub short: String,
    pub summary: String,
    pub message: String,
    pub author_name: String,
    pub author_email: String,
    pub time: i64,
    pub parents: Vec<Oid>,
}

#[derive(Clone, Debug)]
pub struct BranchLabel {
    pub name: String,
    pub is_remote: bool,
    /// remote name of a hidden remote twin (same name, same commit)
    pub twin_remote: Option<String>,
}

#[derive(Clone, Debug)]
pub enum HeadState {
    Branch(String),
    Detached,
    Unborn,
}

pub struct RepoData {
    pub commits: Vec<CommitInfo>,
    pub branches: HashMap<Oid, Vec<BranchLabel>>,
    pub head: HeadState,
    pub head_oid: Option<Oid>,
    pub uncommitted_count: usize,
}

#[derive(Clone, Debug)]
pub struct FileChange {
    pub status: char,
    pub path: String,
    pub additions: usize,
    pub deletions: usize,
    pub binary: bool,
}

#[derive(Clone, Debug, Default)]
pub struct DiffSummary {
    pub files: Vec<FileChange>,
    pub total_files: usize,
    pub additions: usize,
    pub deletions: usize,
}

pub fn open_repo() -> Result<Repository> {
    Repository::discover(".").context("Git repository not found. Please run inside a Git repository.")
}

pub fn repo_name(repo: &Repository) -> String {
    let path = match repo.workdir() {
        Some(p) => p.to_path_buf(),
        None => repo.path().to_path_buf(),
    };
    let path = std::fs::canonicalize(&path).unwrap_or(path);
    path.file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_default()
}

fn lossy(b: &[u8]) -> String {
    String::from_utf8_lossy(b).to_string()
}

pub fn load(repo: &Repository) -> Result<RepoData> {
    // HEAD
    let (head, head_oid) = match repo.head() {
        Ok(h) => {
            let oid = h.target();
            if repo.head_detached().unwrap_or(false) {
                (HeadState::Detached, oid)
            } else if h.is_branch() {
                let name = h.shorthand().map(|s| s.to_string()).unwrap_or_else(|| "HEAD".into());
                (HeadState::Branch(name), oid)
            } else {
                (HeadState::Detached, oid)
            }
        }
        Err(_) => (HeadState::Unborn, None),
    };

    // branches
    let mut locals: Vec<(String, Oid)> = Vec::new();
    let mut remotes: Vec<(String, Oid)> = Vec::new();
    let mut push_oids: Vec<Oid> = Vec::new();
    if let Ok(iter) = repo.branches(None) {
        for b in iter.flatten() {
            let (branch, bt) = b;
            let r = branch.get();
            if r.symbolic_target_bytes().is_some() {
                continue;
