//! Fuzzy matching for branch search.

const BONUS_START: i64 = 16;
const BONUS_SLASH: i64 = 8;
const BONUS_SEPARATOR: i64 = 7;
const BONUS_CAMEL: i64 = 3;
const BONUS_CONSECUTIVE: i64 = 7;
const PENALTY_CASE: i64 = 2;
const PENALTY_GAP_START: i64 = 1;
const PENALTY_GAP_EXTENSION: i64 = 1;

fn is_camel(chars: &[char], i: usize) -> bool {
    i > 0 && chars[i].is_uppercase() && (chars[i - 1].is_lowercase() || chars[i - 1].is_ascii_digit())
}

fn boundary(chars: &[char], i: usize) -> i64 {
    if i == 0 {
        return BONUS_START;
    }
    let p = chars[i - 1];
    if p == '/' {
        BONUS_SLASH
    } else if !p.is_alphanumeric() {
        BONUS_SEPARATOR
    } else if is_camel(chars, i) {
        BONUS_CAMEL
    } else {
        0
    }
}

fn eq_ci(a: char, b: char) -> bool {
    if a == b {
        return true;
    }
    let mut x = a.to_lowercase();
    let mut y = b.to_lowercase();
    loop {
        match (x.next(), y.next()) {
            (None, None) => return true,
            (Some(p), Some(q)) if p == q => continue,
            _ => return false,
        }
    }
}

/// Returns (score, matched char indices) if `query` fuzzily matches `text`.
pub fn fuzzy_match(query: &str, text: &str) -> Option<(i64, Vec<usize>)> {
    let q: Vec<char> = query.chars().collect();
    let t: Vec<char> = text.chars().collect();
    if q.is_empty() {
        return Some((0, vec![]));
    }
    let n = t.len();
    let m = q.len();
    if m > n {
        return None;
    }
    let case_term = |k: usize, i: usize| -> i64 {
        if t[i] == q[k] || is_camel(&t, i) {
            0
        } else {
            -PENALTY_CASE
        }
    };
    let contrib = |k: usize, i: usize, prev: Option<usize>| -> i64 {
        let mut s = case_term(k, i);
        match prev {
            None => s += boundary(&t, i),
            Some(j) => {
                if i == j + 1 {
                    s += BONUS_CONSECUTIVE;
                } else {
                    let gap = (i - j - 1) as i64;
                    s += boundary(&t, i) - (PENALTY_GAP_START + (gap - 1) * PENALTY_GAP_EXTENSION);
                }
            }
        }
        s
    };
    const NEG: i64 = i64::MIN / 4;
    // b[k][i]: best score of matching q[k+1..] given q[k] at i
    let mut b = vec![vec![NEG; n]; m];
    for i in 0..n {
        if eq_ci(t[i], q[m - 1]) {
            b[m - 1][i] = 0;
        }
    }
    for k in (0..m - 1).rev() {
        for i in 0..n {
            if !eq_ci(t[i], q[k]) {
                continue;
            }
            let mut best = NEG;
            for i2 in (i + 1)..n {
                if b[k + 1][i2] == NEG {
                    continue;
                }
                let v = contrib(k + 1, i2, Some(i)) + b[k + 1][i2];
                if v > best {
                    best = v;
                }
            }
            b[k][i] = best;
        }
    }
    // choose start
    let mut best = NEG;
    let mut start = None;
    for i in 0..n {
        if b[0][i] == NEG || !eq_ci(t[i], q[0]) {
            continue;
        }
        let v = contrib(0, i, None) + b[0][i];
        if v >= best {
            best = v;
            start = Some(i);
        }
    }
    let start = start?;
    let mut pos = vec![start];
    let mut cur = start;
    for k in 1..m {
        let target = b[k - 1][cur];
        let mut chosen = None;
        for i2 in (cur + 1)..n {
            if b[k][i2] == NEG {
                continue;
            }
            if contrib(k, i2, Some(cur)) + b[k][i2] == target {
                chosen = Some(i2);
            }
        }
        let c = chosen?;
        pos.push(c);
        cur = c;
    }
    Some((best, pos))
}
