//! Fuzzy matching for branch search.

const BONUS_START: i64 = 16;
const BONUS_SLASH: i64 = 8;
const BONUS_SEPARATOR: i64 = 7;
const BONUS_CAMEL: i64 = 3;
const BONUS_CONSECUTIVE: i64 = 7;
const PENALTY_CASE: i64 = 2;
const PENALTY_GAP_START: i64 = 1;
const PENALTY_GAP_EXTENSION: i64 = 1;

fn is_camel(chars: &[char], i: usize) -> bool {
    i > 0 && chars[i].is_uppercase() && (chars[i - 1].is_lowercase() || chars[i - 1].is_ascii_digit())
}

fn boundary(chars: &[char], i: usize) -> i64 {
    if i == 0 {
        return BONUS_START;
    }
    let p = chars[i - 1];
    if p == '/' {
        BONUS_SLASH
    } else if !p.is_alphanumeric() {
        BONUS_SEPARATOR
    } else if is_camel(chars, i) {
        BONUS_CAMEL
    } else {
        0
    }
}

fn eq_ci(a: char, b: char) -> bool {
    if a == b {
        return true;
    }
    let mut x = a.to_lowercase();
    let mut y = b.to_lowercase();
    loop {
        match (x.next(), y.next()) {
            (None, None) => return true,
            (Some(p), Some(q)) if p == q => continue,
            _ => return false,
        }
    }
}

