//! Application state and event handling.

use crate::config::Config;
use crate::fuzzy;
use crate::git::{self, BranchLabel, DiffSummary, HeadState, RepoData};
use crate::graph::{self, Graph, RowKind};
use anyhow::Result;
use git2::{Oid, Repository};
use ratatui::crossterm::event::{self, Event, KeyCode, KeyEvent, KeyEventKind, KeyModifiers};
use ratatui::widgets::ListState;
use std::sync::mpsc::{channel, Receiver};
use std::time::{Duration, Instant};

pub const PAGE_SIZE: usize = 10;
pub const MESSAGE_DURATION: Duration = Duration::from_secs(5);

#[derive(Clone, Debug)]
pub struct SearchResult {
    pub row: usize,
    pub name: String,
    pub positions: Vec<usize>,
}

#[derive(Clone, Debug)]
pub struct SearchState {
    pub query: String,
    pub results: Vec<SearchResult>,
    pub selected: usize,
    pub offset: usize,
    pub saved_selected: usize,
    pub saved_branch: Option<String>,
    pub saved_offset: usize,
}

#[derive(Clone, Debug)]
pub enum Mode {
    Normal,
    Help,
    Input(String),
    Confirm(String),
    Search(SearchState),
    Error(String),
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum DiffKey {
    Commit(Oid),
    Uncommitted,
}

pub struct App {
    pub repo: Repository,
    pub repo_name: String,
    pub data: RepoData,
    pub graph: Graph,
    pub list_state: ListState,
    pub selected: usize,
    pub selected_branch: Option<String>,
    pub mode: Mode,
    pub diff: Option<DiffSummary>,
    diff_key: Option<DiffKey>,
    pub message: Option<(String, Instant)>,
    pub fetching: bool,
    fetch_rx: Option<Receiver<std::result::Result<(), String>>>,
    fetch_manual: bool,
    config: Config,
    last_refresh: Instant,
    last_fetch: Instant,
    pub should_quit: bool,
    pub commit_area_height: usize,
}

impl App {
    pub fn new(repo: Repository, config: Config) -> Result<App> {
        let repo_name = git::repo_name(&repo);
        let data = git::load(&repo)?;
        let graph = build(&data);
        let mut app = App {
            repo,
            repo_name,
            data,
            graph,
            list_state: ListState::default(),
            selected: 0,
            selected_branch: None,
            mode: Mode::Normal,
            diff: None,
            diff_key: None,
            message: None,
            fetching: false,
            fetch_rx: None,
            fetch_manual: false,
            config,
            last_refresh: Instant::now(),
            last_fetch: Instant::now(),
            should_quit: false,
            commit_area_height: 0,
        };
        if !app.graph.rows.is_empty() {
            app.select(0);
        }
        Ok(app)
    }

    pub fn row_count(&self) -> usize {
        self.graph.rows.len()
    }

    pub fn row_commit(&self, row: usize) -> Option<&git::CommitInfo> {
        match self.graph.rows.get(row)?.kind {
            RowKind::Commit { index, .. } => self.data.commits.get(index),
            _ => None,
        }
    }

    pub fn row_branches(&self, row: usize) -> &[BranchLabel] {
        match self.row_commit(row) {
            Some(c) => self.data.branches.get(&c.oid).map(|v| v.as_slice()).unwrap_or(&[]),
            None => &[],
        }
    }

    pub fn head_branch_name(&self) -> Option<&str> {
        match &self.data.head {
            HeadState::Branch(n) => Some(n.as_str()),
            _ => None,
        }
    }

    pub fn selected_branch_index(&self) -> Option<usize> {
        let name = self.selected_branch.as_ref()?;
        self.row_branches(self.selected).iter().position(|b| &b.name == name)
    }

    fn select(&mut self, row: usize) {
        if self.graph.rows.is_empty() {
            return;
        }
        let row = row.min(self.graph.rows.len() - 1);
        self.selected = row;
        self.list_state.select(Some(row));
        self.selected_branch = self.row_branches(row).first().map(|b| b.name.clone());
        self.update_diff();
    }

    fn update_diff(&mut self) {
        let key = match self.graph.rows.get(self.selected).map(|r| &r.kind) {
            Some(RowKind::Uncommitted) => DiffKey::Uncommitted,
            Some(RowKind::Commit { index, .. }) => DiffKey::Commit(self.data.commits[*index].oid),
            _ => return,
        };
        if self.diff_key.as_ref() == Some(&key) && self.diff.is_some() {
            return;
        }
        let d = match &key {
            DiffKey::Uncommitted => git::uncommitted_diff(&self.repo),
            DiffKey::Commit(oid) => git::commit_diff(&self.repo, *oid),
        };
        self.diff = d.ok();
        self.diff_key = Some(key);
    }

    pub fn refresh(&mut self) {
        self.last_refresh = Instant::now();
        let data = match git::load(&self.repo) {
            Ok(d) => d,
            Err(_) => return,
        };
        self.data = data;
        self.graph = build(&self.data);
        if self.graph.rows.is_empty() {
            self.selected = 0;
            self.list_state.select(None);
            self.selected_branch = None;
            self.diff = None;
            self.diff_key = None;
            return;
        }
        let row = self.selected.min(self.graph.rows.len() - 1);
        self.selected = row;
        self.list_state.select(Some(row));
        if let Some(name) = self.selected_branch.clone() {
            if !self.row_branches(row).iter().any(|b| b.name == name) {
                self.selected_branch = None;
            }
        }
        self.diff_key = None;
        self.update_diff();
    }

    fn start_fetch(&mut self, manual: bool) {
        if self.fetching {
            return;
        }
        let workdir = self
            .repo
            .workdir()
            .map(|p| p.to_path_buf())
            .unwrap_or_else(|| self.repo.path().to_path_buf());
        let (tx, rx) = channel();
        std::thread::spawn(move || {
            let r = git::fetch_origin(&workdir);
            let _ = tx.send(r);
        });
        self.fetch_rx = Some(rx);
        self.fetching = true;
        self.fetch_manual = manual;
        if manual {
            self.message = Some(("Fetching from origin...".to_string(), Instant::now()));
        }
        self.last_fetch = Instant::now();
    }

    pub fn tick(&mut self) {
        if let Some(rx) = &self.fetch_rx {
            if let Ok(res) = rx.try_recv() {
                self.fetch_rx = None;
                self.fetching = false;
                self.last_fetch = Instant::now();
                match res {
                    Ok(()) => {
                        self.message = Some(("Fetched from origin".to_string(), Instant::now()));
                        self.refresh();
                    }
                    Err(e) => {
                        if self.fetch_manual {
                            self.message = None;
                            self.mode = Mode::Error(e);
                        }
                    }
                }
            }
        }
        let cfg = self.config.refresh.clone();
        if cfg.auto_refresh && self.last_refresh.elapsed() >= cfg.refresh_duration() {
            self.refresh();
        }
        if cfg.auto_fetch && !self.fetching && self.last_fetch.elapsed() >= cfg.fetch_duration() {
            self.start_fetch(false);
        }
    }

    pub fn visible_message(&self) -> Option<&str> {
        let (m, t) = self.message.as_ref()?;
        if self.fetching || t.elapsed() < MESSAGE_DURATION {
            Some(m.as_str())
        } else {
            None
        }
    }

    pub fn handle_event(&mut self, ev: Event) {
        if let Event::Key(key) = ev {
            if key.kind != KeyEventKind::Press {
                return;
            }
            self.handle_key(key);
        }
    }

    fn handle_key(&mut self, key: KeyEvent) {
        let mode = std::mem::replace(&mut self.mode, Mode::Normal);
        match mode {
            Mode::Normal => self.handle_normal(key),
            Mode::Help => match key.code {
                KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('?') => {}
                _ => self.mode = Mode::Help,
            },
            Mode::Error(msg) => match key.code {
                KeyCode::Esc | KeyCode::Enter => {}
                _ => self.mode = Mode::Error(msg),
            },
            Mode::Input(mut s) => match key.code {
                KeyCode::Esc => {}
                KeyCode::Enter => {
                    let name = s.trim().to_string();
                    if !name.is_empty() {
                        self.create_branch(&name);
                    }
                }
                KeyCode::Backspace => {
                    s.pop();
                    self.mode = Mode::Input(s);
                }
                KeyCode::Char(c) => {
                    if !key.modifiers.contains(KeyModifiers::CONTROL) {
                        s.push(c);
                    }
                    self.mode = Mode::Input(s);
                }
                _ => self.mode = Mode::Input(s),
            },
            Mode::Confirm(name) => match key.code {
                KeyCode::Char('y') | KeyCode::Char('Y') => {
                    self.delete_branch(&name);
                }
                KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => {}
                _ => self.mode = Mode::Confirm(name),
            },
            Mode::Search(st) => self.handle_search(key, st),
        }
    }

    fn handle_normal(&mut self, key: KeyEvent) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let n = self.row_count();
        match key.code {
            KeyCode::Char('q') | KeyCode::Esc => self.should_quit = true,
            KeyCode::Char('d') if ctrl => {
                if n > 0 {
                    self.select((self.selected + PAGE_SIZE).min(n - 1));
                }
            }
            KeyCode::Char('u') if ctrl => {
                if n > 0 {
                    self.select(self.selected.saturating_sub(PAGE_SIZE));
                }
            }
            KeyCode::Char('j') | KeyCode::Down => {
                if n > 0 && self.selected + 1 < n {
                    self.select(self.selected + 1);
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if n > 0 && self.selected > 0 {
                    self.select(self.selected - 1);
                }
            }
            KeyCode::Char('h') | KeyCode::Left => self.move_branch(-1),
            KeyCode::Char('l') | KeyCode::Right => self.move_branch(1),
            KeyCode::Tab | KeyCode::Char(']') => self.jump_branch(true),
            KeyCode::BackTab | KeyCode::Char('[') => self.jump_branch(false),
            KeyCode::Char('g') | KeyCode::Home => {
                if n > 0 {
                    self.select(0);
                }
            }
            KeyCode::Char('G') | KeyCode::End => {
                if n > 0 {
                    self.select(n - 1);
                }
            }
            KeyCode::Char('@') => self.jump_head(),
            KeyCode::Enter => self.checkout(),
            KeyCode::Char('b') => self.mode = Mode::Input(String::new()),
            KeyCode::Char('d') => {
                if let Some(name) = self.deletable_branch() {
                    self.mode = Mode::Confirm(name);
                }
            }
            KeyCode::Char('f') => self.start_fetch(true),
            KeyCode::Char('/') => {
                self.mode = Mode::Search(SearchState {
                    query: String::new(),
                    results: vec![],
                    selected: 0,
                    offset: 0,
                    saved_selected: self.selected,
                    saved_branch: self.selected_branch.clone(),
                    saved_offset: self.list_state.offset(),
                });
            }
            KeyCode::Char('R') => self.refresh(),
            KeyCode::Char('?') => self.mode = Mode::Help,
            _ => {}
        }
    }

    fn move_branch(&mut self, dir: i32) {
        let branches = self.row_branches(self.selected);
        if branches.is_empty() {
            return;
        }
        let idx = match self.selected_branch_index() {
            Some(i) => i,
            None => return,
        };
        let ni = if dir < 0 {
            idx.saturating_sub(1)
        } else {
            (idx + 1).min(branches.len() - 1)
        };
        self.selected_branch = Some(branches[ni].name.clone());
    }

    fn jump_branch(&mut self, forward: bool) {
        let n = self.row_count();
        if n == 0 {
            return;
        }
        if forward {
            for r in (self.selected + 1)..n {
                if !self.row_branches(r).is_empty() {
                    self.select(r);
                    return;
                }
            }
        } else {
            for r in (0..self.selected).rev() {
                if !self.row_branches(r).is_empty() {
                    self.select(r);
                    return;
                }
            }
        }
    }

    fn head_row(&self) -> Option<usize> {
        let head = self.data.head_oid?;
        self.graph.rows.iter().position(|r| match r.kind {
            RowKind::Commit { index, .. } => self.data.commits[index].oid == head,
            _ => false,
        })
    }

    fn jump_head(&mut self) {
        if let Some(r) = self.head_row() {
            self.select(r);
            if let Some(h) = self.head_branch_name().map(|s| s.to_string()) {
                if self.row_branches(r).iter().any(|b| b.name == h && !b.is_remote) {
                    self.selected_branch = Some(h);
                }
            }
        }
    }

    fn current_branch_label(&self) -> Option<BranchLabel> {
        let branches = self.row_branches(self.selected);
        if let Some(i) = self.selected_branch_index() {
            return branches.get(i).cloned();
        }
        None
    }

    fn deletable_branch(&self) -> Option<String> {
        let b = self.current_branch_label()?;
        if b.is_remote {
            return None;
        }
        if Some(b.name.as_str()) == self.head_branch_name() {
            return None;
        }
        Some(b.name)
    }

    fn checkout(&mut self) {
        let commit = match self.row_commit(self.selected) {
            Some(c) => c.oid,
            None => return,
        };
        let res = if let Some(b) = self.current_branch_label() {
            if b.is_remote {
                git::checkout_remote(&self.repo, &b.name)
            } else {
                git::checkout_local(&self.repo, &b.name)
            }
        } else if let Some(b) = self.row_branches(self.selected).first().cloned() {
            if b.is_remote {
                git::checkout_remote(&self.repo, &b.name)
            } else {
                git::checkout_local(&self.repo, &b.name)
            }
        } else {
            git::checkout_detached(&self.repo, commit)
        };
        match res {
            Ok(()) => self.refresh(),
            Err(e) => {
                self.mode = Mode::Error(format!("{}", e));
                self.refresh();
            }
        }
    }

    fn create_branch(&mut self, name: &str) {
        let oid = match self.row_commit(self.selected) {
            Some(c) => c.oid,
            None => match self.data.head_oid {
                Some(o) => o,
                None => {
                    self.mode = Mode::Error(format!("Failed to create branch '{}'", name));
                    return;
                }
            },
        };
        match git::create_branch(&self.repo, name, oid) {
            Ok(()) => self.refresh(),
            Err(e) => self.mode = Mode::Error(format!("{}", e)),
        }
    }

    fn delete_branch(&mut self, name: &str) {
        match git::delete_branch(&self.repo, name) {
            Ok(()) => self.refresh(),
            Err(e) => self.mode = Mode::Error(format!("{}", e)),
        }
    }

    // ---------------- search ----------------

    fn search_candidates(&self) -> Vec<(usize, String)> {
        let mut v = Vec::new();
        for r in 0..self.row_count() {
            for b in self.row_branches(r) {
                v.push((r, b.name.clone()));
            }
        }
        v
    }

    fn update_search(&mut self, st: &mut SearchState) {
        st.results.clear();
        st.selected = 0;
        st.offset = 0;
        if st.query.is_empty() {
            return;
        }
        let mut scored: Vec<(i64, SearchResult)> = Vec::new();
        for (row, name) in self.search_candidates() {
            if let Some((score, positions)) = fuzzy::fuzzy_match(&st.query, &name) {
                scored.push((score, SearchResult { row, name, positions }));
            }
        }
        scored.sort_by(|a, b| b.0.cmp(&a.0));
        st.results = scored.into_iter().map(|(_, r)| r).collect();
        self.apply_search_selection(st);
    }

    fn apply_search_selection(&mut self, st: &SearchState) {
        if let Some(r) = st.results.get(st.selected) {
            let row = r.row;
            let name = r.name.clone();
            self.select(row);
            self.selected_branch = Some(name);
        }
    }

    fn handle_search(&mut self, key: KeyEvent, mut st: SearchState) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Esc => {
                // restore
                self.selected = st.saved_selected.min(self.row_count().saturating_sub(1));
                if self.row_count() > 0 {
                    self.list_state.select(Some(self.selected));
                    *self.list_state.offset_mut() = st.saved_offset;
                }
                self.selected_branch = st.saved_branch.clone();
                self.update_diff();
                return;
            }
            KeyCode::Enter => {
                return;
            }
            KeyCode::Backspace => {
                if st.query.is_empty() {
                    return;
                }
                st.query.pop();
                self.update_search(&mut st);
            }
            KeyCode::Up => self.search_move(&mut st, -1),
            KeyCode::Down => self.search_move(&mut st, 1),
            KeyCode::Char('k') if ctrl => self.search_move(&mut st, -1),
            KeyCode::Char('j') if ctrl => self.search_move(&mut st, 1),
            KeyCode::Char(c) if !ctrl => {
                st.query.push(c);
                self.update_search(&mut st);
            }
            _ => {}
        }
        self.mode = Mode::Search(st);
    }

    fn search_move(&mut self, st: &mut SearchState, dir: i32) {
        let n = st.results.len();
        if n == 0 {
            return;
        }
        st.selected = if dir < 0 {
            if st.selected == 0 { n - 1 } else { st.selected - 1 }
        } else if st.selected + 1 >= n {
            0
        } else {
            st.selected + 1
        };
        self.apply_search_selection(st);
    }
}

fn build(data: &RepoData) -> Graph {
    let oids: Vec<Oid> = data.commits.iter().map(|c| c.oid).collect();
    let parents: Vec<Vec<Oid>> = data.commits.iter().map(|c| c.parents.clone()).collect();
    let mut g = graph::build_graph(&graph::GraphInput { oids: &oids, parents: &parents });
    if data.uncommitted_count > 0 && data.head_oid.is_some() {
        let head_index = data.commits.iter().position(|c| Some(c.oid) == data.head_oid);
        graph::add_uncommitted(&mut g, head_index);
    }
    g
}

pub fn run(app: &mut App) -> Result<()> {
    let mut terminal = ratatui::init();
    let res = (|| -> Result<()> {
        loop {
            terminal.draw(|f| crate::ui::draw(f, app))?;
            if app.should_quit {
                break;
            }
            if event::poll(Duration::from_millis(100))? {
                let ev = event::read()?;
                app.handle_event(ev);
                if app.should_quit {
                    break;
                }
            }
            app.tick();
        }
        Ok(())
    })();
    ratatui::restore();
    res
}
