/// Per-path line statistics of a diff (additions, deletions).
fn line_stats(diff: &git2::Diff) -> HashMap<String, (usize, usize)> {
    let mut map: HashMap<String, (usize, usize)> = HashMap::new();
    let _ = diff.foreach(
        &mut |_, _| true,
