            match line.origin() {
                '+' => e.0 += 1,
                '-' => e.1 += 1,
                _ => {}
            }
            true
        }),
    );
    map
}

fn collect(diff: &git2::Diff, out: &mut DiffSummary, limit: usize, dedup: bool) -> (usize, usize) {
    let mut stats = line_stats(diff);
